WITH recent_departments AS (SELECT * FROM departments WHERE (dept_name != 'Engineering' AND location = 'Singapore') OR location = 'Tokyo'), Summary AS (SELECT CASE WHEN budget >= 4351000 THEN 'high' WHEN budget >= 1577000 THEN 'mid' ELSE 'low' END AS budget_bucket, AVG(budget) AS avg_budget, MAX(budget) AS max_budget FROM recent_departments GROUP BY CASE WHEN budget >= 4351000 THEN 'high' WHEN budget >= 1577000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, avg_budget FROM Summary ORDER BY budget_bucket DESC;
